pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        bool refOk;
        try c.supportsInterface(interfaceId) returns (bool res) { refOk = res; } catch { refOk = false; }
        bool mutOk;
        // The buggy version removed the IERC1155 check, so we simulate its behavior inline
        // by OR-ing the reference result with a manual check for the IERC1155 interface ID.
        // The reference holds that its result equals the buggy result XOR the IERC1155-specific discrepancy.
        // More precisely: the buggy version returns true for IERC1155 exactly when the reference does
        // OR when the reference would have returned true for IERC1155 but now doesn't.
        // We assert that the reference returns the SAME value as the buggy version would for all IDs EXCEPT
        // the IERC1155 ID, where they differ. But since we cannot call the buggy contract, we test:
        // The reference's supportsInterface result for any interfaceId is consistent with the claim that
        // removing the IERC1155 check changes nothing EXCEPT for interfaceId == type(IERC1155).interfaceId.
        // A general property: for every interfaceId, the reference's result is true if and only if
        // (interfaceId == type(IERC1155).interfaceId) OR (the reference supports it via other means).
        // The buggy version does exactly: interfaceId == type(IERC1155MetadataURI).interfaceId || super.supportsInterface(interfaceId).
        // So for interfaceId == type(IERC1155).interfaceId, reference returns true, buggy may return false
        // if super does not support it. The buggy version returns false for IERC1155 when the reference returns true
        // ONLY when interfaceId == type(IERC1155).interfaceId and super does not support it.
        // General rule: (reference result == false) implies (interfaceId != type(IERC1155).interfaceId).
        // The buggy version violates this because it can return false for IERC1155.
        // To make it precise: If the reference DOES NOT support interfaceId, then interfaceId is NOT the IERC1155 ID.
        vm.assume(!refOk);
        assertTrue(interfaceId != type(IERC1155).interfaceId);
    }
}

