import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // Reference contract C deployed
        bool referenceResult = c.supportsInterface(interfaceId);
        // The buggy version is not deployed; instead, we check that the reference result
        // is consistent with the expected behavior: the reference correctly returns true
        // for IERC1155MetadataURI interfaceId, which the buggy version would fail.
        // We assert that the reference contract's supportsInterface matches the expected
        // result based on interface IDs it should support.
        // The property: for any interfaceId, if it is type(IERC1155).interfaceId or type(IERC1155MetadataURI).interfaceId,
        // supportsInterface must return true. The mutant fails to return true for IERC1155MetadataURI.
        // Since we only have the reference, we assert that the reference returns true for these known IDs.
        // This is a universal property over all bytes4 inputs: the reference returns true iff interfaceId is one of the supported types.
        // The mutant will fail the assertion when interfaceId == type(IERC1155MetadataURI).interfaceId because it returns false.
        assertTrue(
            (interfaceId == type(IERC1155).interfaceId && referenceResult) ||
            (interfaceId == type(IERC1155MetadataURI).interfaceId && referenceResult) ||
            (interfaceId != type(IERC1155).interfaceId && interfaceId != type(IERC1155MetadataURI).interfaceId)
        );
    }
}

