pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 tokenId, uint256 amount, address to) public {
        // Restrict amount to something non-zero and within reasonable range for minting.
        vm.assume(amount > 0 && amount < 1e30);
        // Assume to is not zero address, as mint reverts.
        vm.assume(to != address(0));

        // Setup: create a game item with no transfer restrictions, finite supply = false,
        // price irrelevant if we mint directly via internal (but mint is public, requires Neuron setup).
        // Since mint requires Neuron, we directly call internal _mint using a helper that exposes it,
        // or we can just mint by setting up the Neuron contract. Simpler: create a helper that exposes minting.
        // However, we cannot call internal _mint from test. We need to use the public mint flow.
        // To mint, we need a Neuron instance. We'll deploy a minimal Neuron mock that allows minting.
        // But we cannot import Neuron. Instead, we'll observe that C inherits ERC1155 and has public mint.
        // The mint function requires _neuronInstance and treasury etc. We'll set up by creating a game item,
        // then we can mint as owner by granting ourselves admin.
        // Since we are admin by default (constructor sets isAdmin[owner] to true and owner is address(this)),
        // we can create a game item and then mint tokens to an account by calling mint as a pranked admin with appropriate Neuron allowances mock.
        // But Neuron balance check will fail because _neuronInstance is not set. We need to instantiate Neuron contract.
        // Let's deploy a mock Neuron that gives arbitrary balances and allowances to bypass checks.
        // We'll create a minimal NeuronMock contract after InvMutTest.
        // However, we are not allowed to import Neuron. But we can deploy a contract that matches the expected interface.
        // The mint function calls _neuronInstance.balanceOf, _neuronInstance.approveSpender, _neuronInstance.transferFrom.
        // We'll deploy a contract that has those functions and returns success.
        // Since it's a low-level call, it must be a contract address, not EOA.
        NeuronMock neuron = new NeuronMock();
        c.instantiateNeuronContract(address(neuron));

        // Create a game item with finite supply false, transferable true, itemsRemaining 0, price 0, dailyAllowance huge.
        vm.prank(address(this));
        c.createGameItem("item", "", false, true, 0, 0, type(uint16).max);
        uint256 id = tokenId % c.uniqueTokensOutstanding(); // ensure valid id

        // Now we can mint tokens to 'to' address. We need to prank as someone with enough "balance" in mock Neuron.
        // Mock always returns 0 balance, but we can set it to give whatever we need. We'll adjust mock to return a huge balance.
        neuron.setBalance(to, type(uint256).max);

        // Also approveSpender and transferFrom must succeed. We'll set mock to allow any.
        vm.prank(to);
        c.mint(id, amount);

        // Now the balance of 'to' for tokenId should be exactly 'amount' (since no burns).
        uint256 reported = c.balanceOf(to, id);
        assertTrue(reported == amount);
    }
}

contract NeuronMock {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function setBalance(address user, uint256 bal) public {
        balanceOf[user] = bal;
    }

    function approveSpender(address spender, uint256 amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        require(balanceOf[from] >= amount, "insufficient balance");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

