pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 id, uint256 mintAmount, address to) public {
        vm.assume(to != address(0));
        vm.assume(mintAmount > 0);
        vm.assume(mintAmount <= type(uint128).max);
        // Setup: create a game item that is transferable and allow minting
        c.createGameItem("test", "uri", false, true, 0, 0, 100);
        // Setup: instantiate a mock Neuron to satisfy mint's external call requirements
        // Deploy a minimal Neuron mock that allows approveSpender and transferFrom to succeed
        MockNeuron neuron = new MockNeuron();
        c.instantiateNeuronContract(address(neuron));
        // Mint some amount of the game item to `to`
        vm.prank(to);
        c.mint(id, mintAmount);
        // Record the balance reported by balanceOf
        uint256 reportedBalance = c.balanceOf(to, id);
        // In the reference, the reported balance equals the minted amount.
        // The transfer of the reported amount should succeed.
        // We simulate a transfer by using safeTransferFrom; we need `to` to approve the test contract as operator
        vm.prank(to);
        c.setApprovalForAll(address(this), true);
        // safeTransferFrom will call balanceOf internally for the from balance check.
        // The reference will succeed because reportedBalance equals mintAmount.
        // The bug doubles reportedBalance, causing the internal check to fail because actual balance is mintAmount, not 2*mintAmount.
        bool success;
        try c.safeTransferFrom(to, address(0x1), id, reportedBalance, "") {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success);
    }
}

contract MockNeuron {
    function balanceOf(address) external pure returns (uint256) {
        return type(uint256).max;
    }
    function approveSpender(address, uint256) external pure returns (bool) {
        return true;
    }
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

