        vm.assume(account != address(0));
        vm.assume(id < 1000);
        vm.assume(amount > 0 && amount < 1e36);
        // Setup: mint tokens to the account so balanceOf returns a non-zero value after bug.
        // We need admin to create game item and mint.
        c.adjustAdminAccess(address(this), true);
        c.createGameItem("test", "https://example.com", false, true, 1000000, 0, 1);
        c.mint(id, amount);
        // Transfer the minted tokens to the fuzzed account.
        c.safeTransferFrom(address(this), account, id, amount, "");

        // Get the reported balance from the reference/buggy C.
        uint256 reported = c.balanceOf(account, id);
        vm.assume(reported > 0);

        // Try to transfer the reported balance away; approval is needed.
        vm.prank(account);
        c.setApprovalForAll(address(this), true);

        // The fuzzed account attempts to transfer exactly the reported balance to this test contract.
        vm.prank(account);
        bool success;
        try c.safeTransferFrom(account, address(this), id, reported, "") {
            success = true;
        } catch {
            success = false;
        }
        // The reference must always succeed; the bug reports double the internal balance, causing revert.
        assertTrue(success);
    }
}

