pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(address(this), address(this));
    }

    function testFuzz_property(address account, uint256 tokenId, uint256 mintAmount) public {
        // assume a valid non-zero account and a realistic amount
        vm.assume(account != address(0));
        vm.assume(mintAmount > 0 && mintAmount < 1e18);
        vm.assume(tokenId < 1e6);

        // setup: we need an admin to create a game item and mint tokens
        // address(this) is already admin from constructor
        c.createGameItem("test", "", false, true, 1000, 0, 0);
        // use tokenId 0 which was just created
        // mint tokens to the account
        vm.prank(account);
        // we need to adjust admin to let us mint? Actually owner can add minter etc.
        // But the ERC1155C's internal _mint is not guarded, so we can call it if we have admin?
        // The external mint function requires Neuron checks, so we use the public burn to test?
        // Actually, we can use the fact that the constructor sets isAdmin[address(this)] = true
        // and we can call setAllowedBurningAddresses and then burn/mint?
        // But we need a way to mint tokens to `account` without using the buggy balanceOf.
        // The easiest is to use the owner to add a minter and mint via Neuron, but we don't have Neuron deployed.
        // Instead, we can use the fact that `_mint` is called internally in several places.
        // We can use `createGameItem` which sets attributes, and then `mint` which requires Neuron.
        // Since we don't have Neuron, we can't call `mint`.
        // However, we can use the `burn` function to test balance before and after?
        // We need a way to give tokens to account. Since we control the contract, we can call internal functions via a helper?
        // No, the test must only use public/external surface.
        // We can use `safeTransferFrom` if we have a transferable token and an account that has tokens.
        // The contract constructor doesn't mint any tokens. So we must rely on the `mint` function.
        // The `mint` function requires `_neuronInstance` which is set via `instantiateNeuronContract`.
        // We can deploy a mock Neuron that has a huge balance and allows approvals.
        // That's a helper contract, allowed.

        MockNeuron neuron = new MockNeuron();
        c.instantiateNeuronContract(address(neuron));
        // Now we can call mint, but we need the caller to have enough NRN balance.
        // MockNeuron gives infinite balance to anyone.
        vm.prank(account);
        c.mint(0, mintAmount);

        // Now check balanceOf from the perspective of `account`
        uint256 balanceSelf;
        uint256 balanceOther;

        vm.prank(account);
        balanceSelf = c.balanceOf(account, 0);
        balanceOther = c.balanceOf(account, 0); // called from this contract (different msg.sender)

        // The rule: if account != msg.sender, balanceOf should be > 0 after minting.
        // The bug makes it return 0 for the caller, so balanceSelf will be 0 even though tokens were minted.
        // We assert that for a non-zero mint, the balance should be non-zero when queried by an external caller.
        // To make it a single assertion, we check that at least one of these holds?
        // Actually, the rule is: if tokens are minted to `account`, then at least one call to `balanceOf(account, 0)` with a different msg.sender returns > 0.
        // The bug always returns 0 for the owner, but others see the true balance.
        // So we can assert that the balance reported by a third party (this contract) is > 0.
        // The reference will have balanceOther > 0, the bug will have it > 0 as well, so that doesn't fail.
        // The bug returns 0 for the owner, so we need to show that the owner sees 0 while having tokens.
        // The general rule: after minting to `account`, `balanceOf(account, id)` called by `account` should return > 0.
        // But we can't trust that call in the bug, so we can assert that `balanceOf(account, id)` returns the same value when called by two different parties.
        // Actually, `balanceOf` is a view function, its return value should be independent of msg.sender.
        // The correct contract satisfies: for any account and tokenId, the return value of `balanceOf(account, tokenId)` is the same regardless of who calls it.
        // The bug breaks this because it returns 0 when called by the account itself, but the real value when called by others.
        // So we assert that the two calls return the same value.
        // Since we minted a non-zero amount, balanceSelf != balanceOther if the bug is present.
        assertTrue(balanceSelf == balanceOther);
    }
}

